files.design.sv:
module gates(input A, input B, input C, output D, output E);
  assign D = A | B;
  assign E = D & C;
endmodule

files.testbench.sv:
module t_gates;
  reg A, B, C;
  wire D, E;

  gates g(.A(A), .B(B), .C(C), .D(D), .E(E));

  initial begin
    $monitor("%3t: A=%b B=%b C=%b D=%b E=%b", $time, A, B, C, D, E);
    A = 0; B = 0; C = 0;
    #10 A = 1;
    #10 C = 1;
    #10 A = 0; B = 1;
    #10 $finish;
  end
endmodule

files.design.sv:
module delay(input A, input B, input C, output w1, output E);
  or  #3 (w1, A, B);
  and #2 (E, w1, C);
endmodule

files.testbench.sv:
module t_delay;
  reg A, B, C;
  wire w1, E;

  delay d(.A(A), .B(B), .C(C), .w1(w1), .E(E));

  initial begin
    $monitor("%3t: A=%b B=%b C=%b w1=%b E=%b", $time, A, B, C, w1, E);
    A = 0; B = 0; C = 1;
    #10 A = 1;
    #10 $finish;
  end
endmodule

module t_clock;
  reg clk;

  initial clk = 0;
  always #5 clk = ~clk;

  initial begin
    $monitor("%3t: clk=%b", $time, clk);
    #40 $finish;
  end
endmodule
